    /// <summary>
    /// Populates the <c>METOrderExtractScreenTmp</c> table.
    /// </summary>
    public void populateOrders()
    {
        delete_from METOrderExtractScreenTmpDS;

        if (this.args().parmObject() == null)
        {
            metOrderExtractScreenParameters = METOrderExtractScreenParameters::construct();
        }
        else
        {
            metOrderExtractScreenParameters = this.args().parmObject() as METOrderExtractScreenParameters;
        }

        metOrderExtractScreenParameters.loadLastValue(formStr(METOrderExtractScreen));

        boolean  isExtracted = metOrderExtractScreenParameters.parmExtracted() != METOrderExtractStatus::Extracted;

        METOrderExtractScreenModifyDialog.enabled(isExtracted);
        METSalesPickingListGeneration.enabled(isExtracted);
        SalesTable_ds.allowEdit(isExtracted);
        metOrderExtractScreenProcessor = METOrderExtractScreenProcessor::construct(METOrderExtractScreenTmpDS, metOrderExtractScreenParameters);
        //CS - CB173_SalesOrderExtract - PS
        if (metOrderExtractScreenProcessor)
        {
            metOrderExtractScreenProcessor.parmMETOrderExtractScreenParams(metOrderExtractScreenParameters);
            metOrderExtractScreenTmp = metOrderExtractScreenProcessor.parmMETOrderExtractScreenTmp();
            METOrderExtractScreenTmpDS.linkPhysicalTableInstance(metOrderExtractScreenTmp);
            container   con = metOrderExtractScreenProcessor.parmCon();
            metOrderExtractScreenProcessor.parmMETOrderExtractScreenTmp(metOrderExtractScreenTmp);
            metOrderExtractScreenProcessor.calculateTemp(metOrderExtractScreenTmpDS, con);
            METOrderExtractScreenTmpDS_DS.research();
        }
        
        //CE - CB173_SalesOrderExtract - PS
        totalPallets = metOrderExtractScreenProcessor.parmTotalpallets();

        SalesTable_ds.executeQuery();
        
    }

