        /// <summary>
        /// This method is to control enable/disable of bulk updates
        /// CB173_SalesOrderExtract - PS
        /// </summary>
        public void selectionChanged()
        {
            super();

            int recordsCount = SalesTable_ds.recordsMarked().lastIndex();

            SalesTable  slTbl;
            select firstonly RecId from slTbl; //where slTbl.METSelection == NoYes::Yes;

            METOrderExtractScreenModifyDialog.enabled(true);
            UpdateStatusFormButtonControl.enabled(true);
            if (recordsCount < 1)
            {
                METOrderExtractScreenModifyDialog.enabled(false);
                UpdateStatusFormButtonControl.enabled(false);
            }
            if (slTbl.RecId)
            {
                METOrderExtractScreenModifyDialog.enabled(true);
                UpdateStatusFormButtonControl.enabled(true);
            }
        }

/// <summary>
/// Return wavid for the sales order
/// </summary>
/// <returns>Wave Id</returns>
[SysClientCacheDataMethodAttribute(true)]
display METWaveId displayWaveId()
{
    return METWaveLine::findByDocumentNumber(SalesTable.SalesId).WaveId;
}

        /// <summary>
        /// Return wavid for the sales order
        /// </summary>
        /// <returns>Wave status</returns>
        [SysClientCacheDataMethodAttribute(true)]
        display str displayWaveStatus()
        {
            METWaveTable waveTable;
            METWaveLine  waveLine;

            select firstonly WaveId from waveLine
                where waveLine.DocumentNumber == SalesTable.SalesId
                join WaveStatus from waveTable
                    where waveTable.WaveId == waveLine.WaveId;
            
            return enum2Symbol(enumNum(METCSDWaveStatus), enum2int(waveTable.WaveStatus));
        }

/// <summary>
/// This is an edit method
/// </summary>
/// <param name = "_set">Set</param>
/// <param name = "_salesTable">SalesTable</param>
/// <param name = "_markTrans">MarkTrans</param>
/// <returns>EditValue</returns>
[SysClientCacheDataMethodAttribute(true)]
public edit NoYes editMarkTrans(boolean _set, SalesTable _salesTable, NoYes _markTrans)
{
    if (_set)
    {
        if(!_markTrans)
        {
            if(paMarked.exists(_salesTable.RecId))
            {
                paMarked.remove(_salesTable.RecId);
            }
        }
        else
        {
            paMarked.insert(_salesTable.RecId, _salesTable.SalesId);
        }
    }
    return paMarked.exists(_salesTable.RecId);
}

