        /// <summary>
        /// Calculate totals.
        /// CS - CB173_SalesOrderExtract - PS
        /// </summary>
        [SuppressBPWarning('BPCheckNestedLoopInCode', 'This is reqiored to calculate all the values of selected records.')]
        public void clicked()
        {
            #define.Million(1000000000)
            super();

            METTotalPallets totalPal, estTotalPal;
            Weight          weight, actualWeight;
            Volume          volume, actualVolume;
            METCase         cases, actualCases;
            METBrokenCase   brokenCase, actBrokenCases;
            METInventLocation metInventLocation;

            MapEnumerator mapEnumerator = paMarked.getEnumerator();
            totalPal    = 0;
            estTotalPal = 0;

            while (mapEnumerator.moveNext())
            {
                //int64               recIdLoc    = mapEnumerator.currentKey();
                str                 valueLoc    = mapEnumerator.currentValue();
                //SalesTable          stLoc       = SalesTable::findRecId(recIdLoc);
                //METSalesTable       metsaTblLoc = METSalesTable::findByRefRecId(recIdLoc);
                SalesLine           salesLineLoc;

                while select salesLineLoc where salesLineLoc.SalesId == valueLoc
                {
                    METSalesLine    metsalesLineLoc  = METSalesLine::find(salesLineLoc.RecId);

                    weight          += salesLineLoc.SalesQty * metsalesLineLoc.SalesUnitWeight;
                    volume          += salesLineLoc.SalesQty * metsalesLineLoc.SalesUnitVolume;
                    cases           +=  salesLineLoc.displayMETcases();
                    brokenCase      +=  salesLineLoc.displayMETBrokenCase();
                    actBrokenCases  += salesLineLoc.displayMETActualBrokenCase();
                    actualCases     += salesLineLoc.displayMETActualCases();
                    actualVolume    += salesLineLoc.displayMETActualUnitVolume()/#Million;
                    actualWeight    += salesLineLoc.displayMETActualWeight();

                    //totalPal = 0;
                        
                    metInventLocation = METInventLocation::findByInventLocationId(
                                                                salesLineLoc.inventDim().InventLocationId);
                    if (volume)
                    {
                        totalPal += real2int(roundUp((volume/metInventLocation.WHSPalletVolume), 1));
                        estTotalPal += real2int(roundUp((actualVolume/metInventLocation.WHSPalletVolume), 1));
                    }
                }
            }
           
            SumOfOrderedVolume.realValue(volume);
            SumOfOrderedlWeight.realValue(weight);
            SumOfEstimatedVolume.realValue(actualVolume);
            SumOfEstimatedlWeight.realValue(actualWeight);
            SumOfOrderedCases.value(cases);
            SumOfEstimatedCases.value(actualCases);
            SumOfOrderedBrokenCases.value(brokenCase);
            SumOfEstimatedBrokenCases.value(actBrokenCases);
            totalPallet.value(totalPal);
            TotalEstimatedPallets.value(estTotalPal);

            //element.redraw();
        }

